        "synopsis":  "어릴 적부터 준과 리아의 꿈은 F1 드라이버가 되는 것이었다. 날카로운 주행 실력을 인정받은 리아는 마침내 꿈의 무대에 입성하지만, 본능에 의존한 거침없는 레이싱을 펼치던 준은 끝내 기회를 놓치고 만다. 결국 준은 꿈을 접은 채 택시 운전사로 살아가게 되는데… 그러던 어느 날, 해체 위기에 처한 레이싱 팀을 구하기 위해 미키 마우스와 친구들이 직접 나선다. 그리고 우연히 목격한 준의 과감한 운전에 매료되어 그를 팀에 합류시킨다. 하루아침에 프로 레이싱 무대에 던져진 준. 포기했던 꿈이 그의 눈앞에 다시 펼쳐지고, 마침내 인생 마지막 기회가 찾아온다. 하지만 기쁨도 잠시… 그의 팀 동료가 다름 아닌, 누구보다 치열하게 경쟁해 온 최대의 라이벌, 리아라는 사실을 알게 되는데! 과연 준, 미키와 친구들은 치열한 프로 레이싱, F1 의 세계에서 살아남을 수 있을까?",
